{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.perfumes_retention_overall_sku_level AS WITH orders_union AS ( SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch WHERE UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 UNION ALL SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(DISTINCT order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 ), orders_clean AS ( SELECT phone_no, order_date, order_store, order_sku_group, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) GROUP BY 1,2,3,4 ), cohorts AS ( SELECT phone_no, sku_group AS acq_sku_group, first_order_date, DATE_TRUNC( \'month\', first_order_date ) AS acq_month, acq_channel AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel_sku WHERE first_order_date >= \'2024-01-01\' ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, c.acq_sku_group, o.order_date, o.order_store, o.order_sku_group, o.sales, o.quantity, o.orders, DATEDIFF( \'month\', c.first_order_date, o.order_date ) AS month_diff FROM cohorts c INNER JOIN orders_clean o ON c.phone_no = o.phone_no AND o.order_date >= c.first_order_date ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL::VARCHAR AS acq_store_filter, NULL::VARCHAR AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), metrics AS ( SELECT v.view_type, o.acq_month, o.acq_sku_group AS sku_group, COUNT( DISTINCT o.phone_no ) AS acq_customers, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.sales ELSE 0 END ) AS acq_sales, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.quantity ELSE 0 END ) AS acq_quantity, COUNT( DISTINCT CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m1_customers, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m1_sales, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m1_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m3_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m3_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m3_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m6_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m6_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m6_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m12_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m12_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m12_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m18_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m18_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m18_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m24_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m24_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m24_quantity FROM views v INNER JOIN orders_with_month_diff o ON ( v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter ) GROUP BY 1,2,3 ) SELECT view_type, acq_month, sku_group, acq_customers, acq_sales::INT AS acq_sales, acq_quantity::INT AS acq_quantity, m1_customers, m3_customers, m6_customers, m12_customers, m18_customers, m24_customers, DIV0( m1_customers, acq_customers ) AS m1_customer_retention, DIV0( m3_customers, acq_customers ) AS m3_customer_retention, DIV0( m6_customers, acq_customers ) AS m6_customer_retention, DIV0( m12_customers, acq_customers ) AS m12_customer_retention, DIV0( m18_customers, acq_customers ) AS m18_customer_retention, DIV0( m24_customers, acq_customers ) AS m24_customer_retention, DIV0( m1_sales, acq_sales ) AS m1_sales_retention, DIV0( m3_sales, acq_sales ) AS m3_sales_retention, DIV0( m6_sales, acq_sales ) AS m6_sales_retention, DIV0( m12_sales, acq_sales ) AS m12_sales_retention, DIV0( m18_sales, acq_sales ) AS m18_sales_retention, DIV0( m24_sales, acq_sales ) AS m24_sales_retention, DIV0( m1_quantity, acq_quantity ) AS m1_quantity_retention, DIV0( m3_quantity, acq_quantity ) AS m3_quantity_retention, DIV0( m6_quantity, acq_quantity ) AS m6_quantity_retention, DIV0( m12_quantity, acq_quantity ) AS m12_quantity_retention, DIV0( m18_quantity, acq_quantity ) AS m18_quantity_retention, DIV0( m24_quantity, acq_quantity ) AS m24_quantity_retention FROM metrics ORDER BY view_type, acq_month, sku_group ;",
                    "transaction": true
                }
            ) }}
